/*
 * A039115  Numbers whose base-10 representation has the same number of 0's
 *          and 4's.
 * https://oeis.org/A039115
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 70, u16 n <= 70, u32 n <= 70, u64 n <= 70, u128 n <= 70,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A039115: numbers whose base‑10 representation has the same
 * number of 0's and 4's. Generated by scanning integers and storing
 * the qualifying ones in a cache.  The function is memoised so that
 * subsequent calls are O(1).  The algorithm runs in time O(m) where
 * m is the largest n requested. */
#include <stdint.h>
#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache of computed terms */
    static seq_t *cache = NULL;
    static size_t   cache_cap = 0;
    static size_t   cache_len = 0;
    static uint64_t next_candidate = 1;   /* next integer to test */

    if (n == 0) return 0;   /* undefined for n < 1, return 0 safely */

    /* generate terms until we reach the requested index */
    while (cache_len < n)
    {
        uint64_t  x = next_candidate;
        uint32_t  zeros = 0, fours = 0;

        /* count 0's and 4's in the decimal representation of x */
        if (x == 0) {
            /* not reached because next_candidate starts at 1 */
            zeros = 1;
        } else {
            while (x > 0) {
                unsigned d = x % 10;
                if (d == 0)  ++zeros;
                else if (d == 4) ++fours;
                x /= 10;
            }
        }

        /* if counts are equal, store the value in the cache */
        if (zeros == fours) {
            if (cache_len == cache_cap) {
                size_t new_cap = cache_cap ? cache_cap * 2 : 64;
                seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                if (!tmp) return 0;           /* allocation failure */
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_len++] = (seq_t)next_candidate;
        }

        ++next_candidate;
    }

    return cache[n - 1];
}
